import unittest
from candidate import how_many_times

class TestSubstringOccurrences(unittest.TestCase):
    def test_empty_string(self):
        self.assertEqual(how_many_times('', 'a'), 0)

    def test_single_character_substring(self):
        self.assertEqual(how_many_times('aaa', 'a'), 3)

    def test_overlapping_substring(self):
        self.assertEqual(how_many_times('aaaa', 'aa'), 3)

    def test_substring_not_found(self):
        self.assertEqual(how_many_times('hello', 'world'), 0)

    def test_empty_substring(self):
        self.assertEqual(how_many_times('hello', ''), 6)

    def test_substring_longer_than_string(self):
        self.assertEqual(how_many_times('hello', 'hello-world'), 0)

    def test_string_none(self):
        with self.assertRaises(TypeError):
            how_many_times(None, 'a')

    def test_substring_none(self):
        with self.assertRaises(TypeError):
            how_many_times('hello', None)

    def test_string_and_substring_none(self):
        with self.assertRaises(TypeError):
            how_many_times(None, None)

    def test_non_string_input(self):
        with self.assertRaises(TypeError):
            how_many_times(123, 'a')

    def test_non_string_substring(self):
        with self.assertRaises(TypeError):
            how_many_times('hello', 123)

if __name__ == '__main__':
    unittest.main()
